请对以下 case 进行三维加权评分。

=== case_id ===
Case-15-smart-home-005

=== 用户原始指令 (query.txt) ===
帮我做个睡眠模式吧，几项能打勾，睡眠分数能变，点进去能设置，连上了要能看见

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个睡眠模式吧，几项能打勾，睡眠分数能变，点进去能设置，连上了要能看见",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "卡片标题，表示当前智能家居模式对象。",
        "sampleValue": "睡眠模式"
      }
    },
    "asset": {
      "primaryIcon": {
        "type": "string",
        "description": "睡眠模式主图标素材路径。",
        "sampleValue": "resources/base/media/icon_sleep.png"
      },
      "actionIcon": {
        "type": "string",
        "description": "睡眠设置入口图标素材路径。",
        "sampleValue": "resources/base/media/icon_alarm_clock1.png"
      }
    },
    "sleep": {
      "scoreValue": {
        "type": "number",
        "description": "睡眠分数的数值，用于进度环动态展示。",
        "sampleValue": 86
      },
      "scoreTotal": {
        "type": "number",
        "description": "睡眠分数满分值。",
        "sampleValue": 100
      },
      "scoreText": {
        "type": "string",
        "description": "睡眠分数展示文本。",
        "sampleValue": "86分"
      },
      "quietSelected": {
        "type": "boolean",
        "description": "勿扰项是否已勾选。",
        "sampleValue": true
      },
      "quietLabel": {
        "type": "string",
        "description": "勿扰项标签。",
        "sampleValue": "勿扰"
      },
      "lightSelected": {
        "type": "boolean",
        "description": "关灯项是否已勾选。",
        "sampleValue": true
      },
      "lightLabel": {
        "type": "string",
        "description": "关灯项标签。",
        "sampleValue": "关灯"
      },
      "connectionText": {
        "type": "string",
        "description": "设备或家居系统连接状态展示文本。",
        "sampleValue": "已连接"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "进入睡眠模式设置的短标签。",
        "sampleValue": "设置睡眠"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠图标，适合表达睡眠监督、睡眠模式或夜间休息状态。"
    },
    {
      "src": "resources/base/media/icon_alarm_clock1.png",
      "description": "闹钟图标，适合表达睡眠提醒、入睡设置或夜间模式配置入口。"
    }
  ]
}

